  async read(){const db=await this.open();try{return await new Promise((resolve,reject)=>{const tables={schema:'tuannhatky-unified-tables-v1'},tx=db.transaction(['risk_profiles','trades_journal','simulation_snapshots'],'readonly');for(const name of ['risk_profiles','trades_journal','simulation_snapshots']){const req=tx.objectStore(name).getAll();req.onsuccess=()=>tables[name]=req.result;}tx.oncomplete=()=>resolve(tables.risk_profiles.length?StorageData.fromTables(tables):null);tx.onerror=()=>reject(tx.error||new Error('Đọc IndexedDB thất bại'));tx.onabort=()=>reject(tx.error||new Error('Đọc IndexedDB bị hủy'));});}finally{db.close();}},
