    const rows=[];let cursor=null;do{const page=await this.request('/api/trades?limit=1000&projection=analysis'+(cursor?'&cursor='+encodeURIComponent(cursor):''));if(page.owner!==this.owner||!Array.isArray(page.trades))throw Error('Dữ liệu Classic không hợp lệ');rows.push(...page.trades);cursor=page.next;this.message='Đang tải '+rows.length.toLocaleString('vi-VN')+' lệnh từ Classic…';this.status();}while(cursor);
